   "sintesis": "Donald Trump, Xi Jinping y Vladimir Putin celebraron en Shenzhen la primera reunión trilateral entre EE.UU., China y Rusia. Los tres mandatarios se sentaron alrededor de una gran mesa circular en Kylin Villa, un complejo turístico junto a un lago, donde hicieron sus declaraciones ante la prensa.",
   "puntos": [
    "Donald Trump, Xi Jinping y Vladimir Putin celebraron en Shenzhen la primera reunión trilateral entre EE.UU., China y Rusia.",
    "Los tres mandatarios se sentaron alrededor de una gran mesa circular en Kylin Villa, un complejo turístico junto a un lago, donde hicieron sus declaraciones ante la prensa.",
    "\"China, Rusia y EE.UU. deben dar ejemplo cooperando para afrontar los desafíos mundiales, mantener conjuntamente la paz y la estabilidad y contribuir en mayor medida al progreso de la humanidad\", afirmó el líder chino al iniciar la reunión."
   ],
