   "titulo": "Cien días de deriva: la salud entre la improvisación y el continuismo",
   "resumen": "El gobierno de Fujimori diluye las reformas prometidas y muestra dificultades para conducir un sector golpeado por epidemias y amenazado por El Niño.",
   "fuente": "Salud con Lupa",
   "url": "https://saludconlupa.com/opinion/cien-dias-de-deriva-la-salud-entre-la-improvisacion-y-el-continuismo/",
   "fecha": "2026-11-02T21:14:00Z",
   "tipo": "independiente",
   "genero": "opinion",
